'use client';

import { FormEvent, useEffect, useRef, useState } from 'react';
import { buildDayPlan, categoryAverage, isoToday, nextMove, overallAverage, projectedSubjectScore, solveNextGrade, subjectScore, taskPriority, uid } from './engine';
import type { AppState, Category, Exam, Goal, Habit, OsAction, Subject, Task, Workout } from './types';
import { CommandCenter } from './signature';

const STORAGE_KEY = 'leon-os-v5';
const DEFAULT_STATE: AppState = {
  version: 5,
  onboardingDone: false,
  profile: {
    name: '', schoolType: '', classLevel: '', state: 'Baden-Württemberg', targetAverage: 1.5,
    focusMinutes: 40, weeklySportTarget: 3,
    weekdayHomeTimes: { '1':'17:00','2':'17:00','3':'14:00','4':'17:00','5':'14:00' }
  },
  subjects: [], tasks: [], exams: [], events: [], habits: [], workouts: [], goals: [], memory: [], chat: [], dayPlan: []
};

type View = 'today'|'school'|'plan'|'progress'|'os';
type ModalKind = 'subject'|'grade'|'task'|'exam'|'event'|'habit'|'workout'|'goal'|'profile'|null;
type EditRef = { type: Exclude<ModalKind,null>; id?: string; subjectId?: string } | null;

export default function Page() {
  const [state,setState] = useState<AppState>(DEFAULT_STATE);
  const [loaded,setLoaded] = useState(false);
  const [view,setView] = useState<View>('today');
  const [selectedSubject,setSelectedSubject] = useState<string|null>(null);
  const [modal,setModal] = useState<ModalKind>(null);
  const [editRef,setEditRef] = useState<EditRef>(null);
  const [toast,setToast] = useState('');

  useEffect(()=>{
    try {
      const raw=localStorage.getItem(STORAGE_KEY);
      if(raw){ const parsed=JSON.parse(raw); if(parsed?.version===5) setState(parsed); }
    } catch {}
    setLoaded(true);
  },[]);
  useEffect(()=>{ if(loaded) localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); },[state,loaded]);
  useEffect(()=>{ if(toast){ const t=setTimeout(()=>setToast(''),2400); return()=>clearTimeout(t); } },[toast]);

  const openModal=(kind:Exclude<ModalKind,null>, ref?:EditRef)=>{setModal(kind);setEditRef(ref||{type:kind});};
  const closeModal=()=>{setModal(null);setEditRef(null);};
  const notify=(s:string)=>setToast(s);

  if(!loaded) return <div className="onboarding"><div className="muted">Leon OS lädt…</div></div>;
  if(!state.onboardingDone) return <Onboarding state={state} onDone={s=>{setState(s);notify('OS eingerichtet');}}/>;

  const avg=overallAverage(state.subjects);
  const move=nextMove(state);
  const today=isoToday();
  const todayEvents=state.events.filter(e=>e.date===today).sort((a,b)=>a.start.localeCompare(b.start));

  function nav(v:View){setView(v);if(v!=='school')setSelectedSubject(null);}
  function applyAction(action:OsAction){
    setState(prev=>{
      const s=structuredClone(prev) as AppState;
      switch(action.type){
        case 'add_subject': {
          const total=action.payload.categories.reduce((a,c)=>a+c.weight,0);
          if(Math.abs(total-100)>0.01) return prev;
          s.subjects.push({id:uid(),name:action.payload.name,target:action.payload.target,notes:'',categories:action.payload.categories.map(c=>({id:uid(),...c})),grades:[]});break;
        }
        case 'update_subject': {
          const sub=s.subjects.find(x=>x.id===action.payload.subjectId); if(!sub)break;
          if(action.payload.name!==null)sub.name=action.payload.name;
          if(action.payload.target!==null)sub.target=action.payload.target;
          if(action.payload.notes!==null)sub.notes=action.payload.notes;
          if(action.payload.categories){
            const old=sub.categories;
            sub.categories=action.payload.categories.map(c=>{const match=old.find(o=>o.name.toLowerCase()===c.name.toLowerCase());return{id:match?.id||uid(),name:c.name,weight:c.weight};});
          }
          break;
        }
        case 'add_grade': {const sub=s.subjects.find(x=>x.id===action.payload.subjectId);if(sub)sub.grades.push({id:uid(),...action.payload});break;}
        case 'add_exam': s.exams.push({id:uid(),progress:0,...action.payload});break;
        case 'add_task': s.tasks.push({id:uid(),status:'open',...action.payload});break;
        case 'update_task': {const t=s.tasks.find(x=>x.id===action.payload.taskId);if(t){for(const k of ['title','dueDate','duration','importance','notes','status'] as const){const val=action.payload[k];if(val!==null)(t as any)[k]=val;}}break;}
        case 'add_event': s.events.push({id:uid(),title:action.payload.title,date:action.payload.date,start:action.payload.start,duration:action.payload.duration,type:action.payload.eventType});break;
        case 'log_workout': s.workouts.push({id:uid(),type:action.payload.workoutType,date:action.payload.date,duration:action.payload.duration,distance:action.payload.distance,notes:action.payload.notes});break;
        case 'remember': s.memory.push({id:uid(),text:action.payload.text,createdAt:new Date().toISOString()});break;
        case 'set_day_plan': s.dayPlan=action.payload.blocks;break;
      }
      return s;
    });
  }

  return <div className="app">
    <div className="shell">
      <aside className="sidebar">
        <div className="brand"><div className="mark">L</div>Leon OS</div>
        <div className="nav">
          <NavButton active={view==='today'} icon="◉" label="Today" onClick={()=>nav('today')}/>
          <NavButton active={view==='school'} icon="□" label="School" onClick={()=>nav('school')}/>
          <NavButton active={view==='plan'} icon="◇" label="Plan" onClick={()=>nav('plan')}/>
          <NavButton active={false} icon="▣" label="Kalender" onClick={()=>window.location.assign('/google-calendar')}/>
          <NavButton active={view==='progress'} icon="↗" label="Progress" onClick={()=>nav('progress')}/>
          <NavButton active={view==='os'} icon="✦" label="OS" onClick={()=>nav('os')}/>
        </div>
        <div className="sidefoot">AI-assisted planning<br/>Berechnungen bleiben deterministisch.</div>
      </aside>
      <main className="main"><div className="content">
        {view==='today' && <TodayView state={state} move={move} avg={avg} todayEvents={todayEvents} openModal={openModal} setState={setState} goOS={()=>nav('os')} notify={notify}/>} 
        {view==='school' && <SchoolView state={state} selected={selectedSubject} setSelected={setSelectedSubject} openModal={openModal} setState={setState} notify={notify}/>} 
        {view==='plan' && <PlanView state={state} openModal={openModal} setState={setState} notify={notify}/>} 
        {view==='progress' && <ProgressView state={state} avg={avg} openModal={openModal} setState={setState}/>} 
        {view==='os' && <OSView state={state} setState={setState} applyAction={applyAction}/>} 
      </div></main>
    </div>
    <div className="mobilebar">
      {([['today','◉','Today'],['school','□','School'],['plan','◇','Plan'],['progress','↗','Progress'],['os','✦','OS']] as [View,string,string][]).map(([v,i,l])=><button key={v} className={view===v?'active':''} onClick={()=>nav(v)}><span>{i}</span>{l}</button>)}
    </div>
    {modal && <EditorModal kind={modal} editRef={editRef} state={state} setState={setState} close={closeModal} notify={notify}/>} 
    {toast && <div className="toast">{toast}</div>}
  </div>;
}

function NavButton({active,icon,label,onClick}:{active:boolean;icon:string;label:string;onClick:()=>void}){return <button className={`navbtn ${active?'active':''}`} onClick={onClick}><span className="navicon">{icon}</span>{label}</button>}
function Header({eyebrow,title,children}:{eyebrow:React.ReactNode;title:string;children?:React.ReactNode}){return <div className="topbar"><div><div className="eyebrow">{eyebrow}</div><h1 className="title">{title}</h1></div><div className="topactions">{children}</div></div>}

function TodayView({state,move,avg,todayEvents,openModal,setState,goOS,notify}:{state:AppState;move:Task|null;avg:number|null;todayEvents:any[];openModal:(k:any,r?:any)=>void;setState:React.Dispatch<React.SetStateAction<AppState>>;goOS:()=>void;notify:(s:string)=>void}){
  const today=isoToday(); const open=state.tasks.filter(t=>t.status==='open').sort((a,b)=>taskPriority(b,state)-taskPriority(a,state));
  const exams=state.exams.filter(e=>new Date(e.date)>=new Date(today)).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);
  const plan=state.dayPlan;
  return <>
    <Header eyebrow={new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'long'}).format(new Date())} title={`Guten Morgen${state.profile.name?`, ${state.profile.name}`:''}.`}>
      <button className="btn" onClick={()=>window.location.assign('/google-calendar')}>Kalender</button><button className="btn" onClick={()=>openModal('profile',{type:'profile'})}>Einstellungen</button><button className="btn primary" onClick={goOS}>Ask OS</button>
    </Header>
    <CommandCenter state={state} move={move} goOS={goOS}/>
    <div className="grid two">
      <div className="card hero">
        <div className="eyebrow">NEXT MOVE</div>
        {move?<div className="nextmove"><div><div className="move-title">{move.title}</div><div className="reason">{priorityReason(move,state)}</div><div style={{marginTop:15,display:'flex',gap:8}}><span className="pill">{move.duration} min</span>{move.dueDate&&<span className="pill">fällig {formatDate(move.dueDate)}</span>}</div></div><button className="btn blue" onClick={()=>{setState(p=>({...p,tasks:p.tasks.map(t=>t.id===move.id?{...t,status:'done'}:t)}));notify('Task erledigt');}}>Erledigt</button></div>:<div className="empty">Noch keine offenen Aufgaben. Füge einen Task hinzu oder sage OS, was ansteht.</div>}
      </div>
      <div className="card"><h3 className="section-title">Status</h3><div className="metricrow"><div><div className="bigmetric">{avg?avg.toFixed(2):'—'}</div><div className="small muted">rechnerischer Schulschnitt</div></div><span className="pill blue">Ziel {state.profile.targetAverage.toFixed(1)}</span></div><div style={{height:18}}/><div className="split small"><span className="muted">Offene Tasks</span><strong>{open.length}</strong></div><div className="split small" style={{marginTop:9}}><span className="muted">Prüfungen</span><strong>{exams.length}</strong></div></div>
    </div>
    <div style={{height:16}}/>
    <div className="grid two">
      <div className="card"><div className="split"><h3 className="section-title">Heute</h3><button className="btn small" onClick={()=>{const blocks=buildDayPlan(state,today);setState(p=>({...p,dayPlan:blocks}));notify('Tag neu geplant');}}>Smart planen</button></div>
        {plan.length?<div className="schedule">{plan.map(b=><div className="block" key={b.id}><div className="time">{b.start}</div><div><div className="rowtitle">{b.title}</div><div className="rowsub">{b.duration} Minuten · {b.kind}</div></div><span className="pill">{b.duration}m</span></div>)}</div>:todayEvents.length?<div className="schedule">{todayEvents.map(e=><div className="block" key={e.id}><div className="time">{e.start}</div><div className="rowtitle">{e.title}</div><span className="pill">{e.duration}m</span></div>)}</div>:<div className="empty">Noch kein Tagesplan. „Smart planen“ nutzt deine echten Tasks und Termine.</div>}
      </div>
      <div className="card"><div className="split"><h3 className="section-title">Als Nächstes</h3><button className="btn small" onClick={()=>openModal('task',{type:'task'})}>Task +</button></div>
        {open.length?<div className="list">{open.slice(0,5).map(t=><div className="row" key={t.id}><button className="checkbox" onClick={()=>setState(p=>({...p,tasks:p.tasks.map(x=>x.id===t.id?{...x,status:'done'}:x)}))}/><div className="rowmain"><div className="rowtitle">{t.title}</div><div className="rowsub">{t.dueDate?formatDate(t.dueDate):'ohne Deadline'} · {t.duration} min</div></div><button className="btn small ghost" onClick={()=>openModal('task',{type:'task',id:t.id})}>Bearbeiten</button></div>)}</div>:<div className="empty">Keine offenen Aufgaben.</div>}
      </div>
    </div>
  </>
}

function SchoolView({state,selected,setSelected,openModal,setState,notify}:{state:AppState;selected:string|null;setSelected:(x:string|null)=>void;openModal:(k:any,r?:any)=>void;setState:React.Dispatch<React.SetStateAction<AppState>>;notify:(s:string)=>void}){
  const subject=selected?state.subjects.find(s=>s.id===selected):null;
  if(subject) return <SubjectDetail subject={subject} state={state} back={()=>setSelected(null)} openModal={openModal} setState={setState} notify={notify}/>;
  return <><Header eyebrow="SCHULE" title="Fächer & Noten"><button className="btn primary" onClick={()=>openModal('subject',{type:'subject'})}>Fach hinzufügen</button></Header>
    <div className="notice">Gewichtungen sind pro Fach frei editierbar. In Baden-Württemberg ist z. B. 60/40 nicht landesweit automatisch vorgeschrieben; die App zeigt deshalb einen rechnerischen Stand, keine garantierte Zeugnisnote.</div><div style={{height:16}}/>
    {state.subjects.length?<div className="subjects">{state.subjects.map(s=>{const sc=subjectScore(s);return <button className="subject-card" key={s.id} onClick={()=>setSelected(s.id)}><div className="split"><div className="subject-name">{s.name}</div><span className="pill">Ziel {s.target.toFixed(1)}</span></div><div className="subject-score">{sc.value?sc.value.toFixed(2):'—'}</div><div className="small muted">{sc.complete?'rechnerischer Stand':'vorläufig · unvollständig'}</div><div style={{height:13}}/><div className="progress"><span style={{width:`${Math.max(0,Math.min(100,((6-(sc.value||6))/5)*100))}%`}}/></div></button>})}</div>:<div className="empty">Noch keine Fächer. Lege nur deine echten Fächer an.</div>}
  </>
}

function SubjectDetail({subject,state,back,openModal,setState,notify}:{subject:Subject;state:AppState;back:()=>void;openModal:(k:any,r?:any)=>void;setState:React.Dispatch<React.SetStateAction<AppState>>;notify:(s:string)=>void}){
  const sc=subjectScore(subject); const [targetCat,setTargetCat]=useState(subject.categories[0]?.id||''); const [hypo,setHypo]=useState(1.5); const projection=targetCat?projectedSubjectScore(subject,targetCat,hypo,1):null; const solve=targetCat?solveNextGrade(subject,subject.target,targetCat,1)[0]:null;
  return <><Header eyebrow={<button className="btn small ghost" onClick={back}>← Alle Fächer</button>} title={subject.name}><button className="btn" onClick={()=>openModal('subject',{type:'subject',id:subject.id})}>Fach bearbeiten</button><button className="btn primary" onClick={()=>openModal('grade',{type:'grade',subjectId:subject.id})}>Note hinzufügen</button></Header>
    <div className="kpis"><div className="kpi"><div className="v">{sc.value?sc.value.toFixed(2):'—'}</div><div className="l">Rechnerischer Stand</div></div><div className="kpi"><div className="v">{subject.target.toFixed(1)}</div><div className="l">Ziel</div></div><div className="kpi"><div className="v">{subject.grades.length}</div><div className="l">Leistungen</div></div><div className="kpi"><div className="v">{sc.complete?'voll':'vorl.'}</div><div className="l">Datenstatus</div></div></div><div style={{height:16}}/>
    <div className="grid two"><div className="card"><h3 className="section-title">Leistungen</h3>{subject.grades.length?<div className="list">{subject.grades.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(g=>{const cat=subject.categories.find(c=>c.id===g.categoryId);return <div className="row" key={g.id}><div className="rowmain"><div className="rowtitle">{g.label||cat?.name||'Note'}</div><div className="rowsub">{cat?.name||'Kategorie'} · {formatDate(g.date)} · {g.multiplier}×</div></div><strong>{g.value.toFixed(1)}</strong><button className="btn small ghost" onClick={()=>openModal('grade',{type:'grade',id:g.id,subjectId:subject.id})}>Bearbeiten</button></div>})}</div>:<div className="empty">Noch keine Noten eingetragen.</div>}</div>
      <div className="grid"><div className="card"><h3 className="section-title">Gewichtung</h3>{subject.categories.map(c=><div className="row" key={c.id}><div className="rowmain"><div className="rowtitle">{c.name}</div><div className="rowsub">Schnitt {categoryAverage(subject,c.id)?.toFixed(2)||'—'}</div></div><strong>{c.weight}%</strong></div>)}</div>
      <div className="card"><h3 className="section-title">Was-wäre-wenn?</h3>{subject.categories.length?<div className="form"><div className="field"><span className="label">Kategorie</span><select className="select" value={targetCat} onChange={e=>setTargetCat(e.target.value)}>{subject.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><div className="field"><span className="label">Nächste Note</span><NumberInput className="input" min="1" max="6" step="0.1" value={hypo} onChange={e=>setHypo(Number(e.target.value))}/></div><div className="split"><span className="small muted">Danach ungefähr</span><strong>{projection?.toFixed(2)||'—'}</strong></div><div className="split"><span className="small muted">Für Ziel {subject.target.toFixed(1)} nötig</span><strong>{solve?.needed?.toFixed(2)||'nicht mit einer Note erreichbar'}</strong></div></div>:<div className="empty">Lege zuerst Kategorien an.</div>}</div></div>
    </div>
  </>
}

function PlanView({state,openModal,setState,notify}:{state:AppState;openModal:(k:any,r?:any)=>void;setState:React.Dispatch<React.SetStateAction<AppState>>;notify:(s:string)=>void}){
  const [tab,setTab]=useState<'tasks'|'exams'|'events'>('tasks'); const sorted=state.tasks.slice().sort((a,b)=>taskPriority(b,state)-taskPriority(a,state));
  return <><Header eyebrow="PLAN" title="Aufgaben & Kalender"><button className="btn" onClick={()=>window.location.assign('/google-calendar')}>Google Kalender</button><button className="btn" onClick={()=>openModal('event',{type:'event'})}>Termin +</button><button className="btn" onClick={()=>openModal('exam',{type:'exam'})}>Prüfung +</button><button className="btn primary" onClick={()=>openModal('task',{type:'task'})}>Task +</button></Header>
    <div className="tabs"><button className={`tab ${tab==='tasks'?'active':''}`} onClick={()=>setTab('tasks')}>Tasks</button><button className={`tab ${tab==='exams'?'active':''}`} onClick={()=>setTab('exams')}>Prüfungen</button><button className={`tab ${tab==='events'?'active':''}`} onClick={()=>setTab('events')}>Termine</button></div>
    <div className="card">{tab==='tasks'&&(sorted.length?<div className="list">{sorted.map(t=><div className="row" key={t.id}><button className={`checkbox ${t.status==='done'?'done':''}`} onClick={()=>setState(p=>({...p,tasks:p.tasks.map(x=>x.id===t.id?{...x,status:x.status==='done'?'open':'done'}:x)}))}/><div className="rowmain"><div className="rowtitle" style={{textDecoration:t.status==='done'?'line-through':'none'}}>{t.title}</div><div className="rowsub">{state.subjects.find(s=>s.id===t.subjectId)?.name||'Allgemein'} · {t.dueDate?formatDate(t.dueDate):'ohne Deadline'} · {t.duration} min · Prio {t.importance}/5</div></div><button className="btn small" onClick={()=>openModal('task',{type:'task',id:t.id})}>Bearbeiten</button></div>)}</div>:<div className="empty">Keine Tasks.</div>)}
      {tab==='exams'&&(state.exams.length?<div className="list">{state.exams.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=><div className="row" key={e.id}><div className="rowmain"><div className="rowtitle">{e.title}</div><div className="rowsub">{state.subjects.find(s=>s.id===e.subjectId)?.name||'Fach'} · {formatDate(e.date)} · Lernschätzung {e.estimatedMinutes} min</div></div><span className="pill">{daysUntil(e.date)} Tage</span><button className="btn small" onClick={()=>openModal('exam',{type:'exam',id:e.id})}>Bearbeiten</button></div>)}</div>:<div className="empty">Keine Prüfungen.</div>)}
      {tab==='events'&&(state.events.length?<div className="list">{state.events.slice().sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).map(e=><div className="row" key={e.id}><div className="rowmain"><div className="rowtitle">{e.title}</div><div className="rowsub">{formatDate(e.date)} · {e.start} · {e.duration} min · {e.type}</div></div><button className="btn small" onClick={()=>openModal('event',{type:'event',id:e.id})}>Bearbeiten</button></div>)}</div>:<div className="empty">Keine Termine.</div>)}</div>
  </>
}

function ProgressView({state,avg,openModal,setState}:{state:AppState;avg:number|null;openModal:(k:any,r?:any)=>void;setState:React.Dispatch<React.SetStateAction<AppState>>}){
  const weekWorkouts=state.workouts.filter(w=>Date.now()-new Date(`${w.date}T12:00:00`).getTime()<=7*86400000).length;
  const done=state.tasks.filter(t=>t.status==='done').length; const consistency=state.habits.length?Math.round(state.habits.reduce((sum,h)=>sum+(h.logs.includes(isoToday())?1:0),0)/state.habits.length*100):0;
  return <><Header eyebrow="PROGRESS" title="Fortschritt"><button className="btn" onClick={()=>openModal('workout',{type:'workout'})}>Workout +</button><button className="btn" onClick={()=>openModal('habit',{type:'habit'})}>Habit +</button><button className="btn primary" onClick={()=>openModal('goal',{type:'goal'})}>Ziel +</button></Header>
    <div className="kpis"><div className="kpi"><div className="v">{avg?.toFixed(2)||'—'}</div><div className="l">Schulschnitt</div></div><div className="kpi"><div className="v">{done}</div><div className="l">Tasks erledigt</div></div><div className="kpi"><div className="v">{weekWorkouts}/{state.profile.weeklySportTarget}</div><div className="l">Sport diese Woche</div></div><div className="kpi"><div className="v">{consistency}%</div><div className="l">Habits heute</div></div></div><div style={{height:16}}/>
    <div className="grid three"><div className="card"><div className="split"><h3 className="section-title">Habits</h3><button className="btn small" onClick={()=>openModal('habit',{type:'habit'})}>+</button></div>{state.habits.length?<div className="list">{state.habits.map(h=><div className="row" key={h.id}><button className={`checkbox ${h.logs.includes(isoToday())?'done':''}`} onClick={()=>{const today=isoToday();setState(p=>({...p,habits:p.habits.map(x=>x.id===h.id?{...x,logs:x.logs.includes(today)?x.logs.filter(d=>d!==today):[...x.logs,today]}:x)}));}}/><div className="rowmain"><div className="rowtitle">{h.name}</div><div className="rowsub">{h.logs.length} Check-ins</div></div><button className="btn small ghost" onClick={()=>openModal('habit',{type:'habit',id:h.id})}>Edit</button></div>)}</div>:<div className="empty">Keine Habits.</div>}</div>
      <div className="card"><div className="split"><h3 className="section-title">Sport</h3><button className="btn small" onClick={()=>openModal('workout',{type:'workout'})}>+</button></div>{state.workouts.length?<div className="list">{state.workouts.slice(-5).reverse().map(w=><div className="row" key={w.id}><div className="rowmain"><div className="rowtitle">{w.type}</div><div className="rowsub">{formatDate(w.date)} · {w.duration} min{w.distance?` · ${w.distance} km`:''}</div></div><button className="btn small ghost" onClick={()=>openModal('workout',{type:'workout',id:w.id})}>Edit</button></div>)}</div>:<div className="empty">Noch keine Workouts.</div>}</div>
      <div className="card"><div className="split"><h3 className="section-title">Ziele</h3><button className="btn small" onClick={()=>openModal('goal',{type:'goal'})}>+</button></div>{state.goals.length?<div className="list">{state.goals.map(g=><div className="row" key={g.id}><div className="rowmain"><div className="rowtitle">{g.title}</div><div className="rowsub">{g.category} · {g.progress}%</div><div className="progress" style={{marginTop:8}}><span style={{width:`${g.progress}%`}}/></div></div><button className="btn small ghost" onClick={()=>openModal('goal',{type:'goal',id:g.id})}>Edit</button></div>)}</div>:<div className="empty">Noch keine Ziele.</div>}</div></div>
  </>
}

function OSView({state,setState,applyAction}:{state:AppState;setState:React.Dispatch<React.SetStateAction<AppState>>;applyAction:(a:OsAction)=>void}){
  const [text,setText]=useState(''); const [sending,setSending]=useState(false); const endRef=useRef<HTMLDivElement|null>(null);
  useEffect(()=>{endRef.current?.scrollIntoView({behavior:'smooth'});},[state.chat,sending]);
  const send=async(raw?:string)=>{const message=(raw??text).trim();if(!message||sending)return;setText('');const userMsg={id:uid(),role:'user' as const,content:message,createdAt:new Date().toISOString()};const history=state.chat.slice(-10);setState(p=>({...p,chat:[...p.chat,userMsg]}));setSending(true);
    try{const res=await fetch('/api/os',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message,state,history})});const data=await res.json();if(!data.ok)throw new Error(data.error||'AI error');if(Array.isArray(data.actions))data.actions.forEach((a:OsAction)=>applyAction(a));setState(p=>({...p,chat:[...p.chat,{id:uid(),role:'assistant',content:data.text||'Erledigt.',createdAt:new Date().toISOString()}]}));}catch(e:any){setState(p=>({...p,chat:[...p.chat,{id:uid(),role:'assistant',content:`Ich konnte die Anfrage nicht ausführen: ${e.message}`,createdAt:new Date().toISOString()}]}));}finally{setSending(false);}
  };
  return <><Header eyebrow="LEON OS" title="Dein persönlicher Assistent"><span className="pill blue">AI · GPT‑5.6</span></Header><div className="notice">OS ist eine KI. Es kann App-Daten nur über kontrollierte Werkzeuge ändern. Notenberechnungen und Tagesplanung laufen über feste Rechenlogik.</div><div style={{height:14}}/><div className="chatwrap"><div className="messages">{state.chat.length===0&&<div className="message assistant"><div className="assistant-name">Leon OS</div>Frag frei oder gib mir etwas zum Eintragen. Zum Beispiel: „Ich schreibe nächsten Freitag Mathe“, „Was brauche ich in Physik für 1,5?“ oder „Plane meinen Nachmittag.“</div>}{state.chat.map(m=><div className={`message ${m.role}`} key={m.id}>{m.role==='assistant'&&<div className="assistant-name">Leon OS</div>}{m.content}</div>)}{sending&&<div className="message assistant"><div className="assistant-name">Leon OS</div><span className="muted">Denkt und prüft deine Daten…</span></div>}<div ref={endRef}/></div><div className="composer"><div className="composerbox"><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Ask your OS…" onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}}}/><button className="send" onClick={()=>send()}>↑</button></div><div className="suggestions"><button className="suggestion" onClick={()=>send('Plane meinen heutigen Nachmittag.')}>Heute planen</button><button className="suggestion" onClick={()=>send('Welche Sache hat gerade die höchste Priorität und warum?')}>Priorität</button><button className="suggestion" onClick={()=>send('Wie läuft meine Woche bisher?')}>Wochencheck</button><button className="suggestion" onClick={()=>send('Was weißt du über mich?')}>Memory</button></div></div></div></>
}

function EditorModal({kind,editRef,state,setState,close,notify}:{kind:Exclude<ModalKind,null>;editRef:EditRef;state:AppState;setState:React.Dispatch<React.SetStateAction<AppState>>;close:()=>void;notify:(s:string)=>void}){
  const id=editRef?.id;
  if(kind==='subject') return <SubjectForm existing={id?state.subjects.find(s=>s.id===id):undefined} state={state} setState={setState} close={close} notify={notify}/>;
  if(kind==='grade') return <GradeForm subject={state.subjects.find(s=>s.id===editRef?.subjectId)!} existing={id?state.subjects.find(s=>s.id===editRef?.subjectId)?.grades.find(g=>g.id===id):undefined} setState={setState} close={close} notify={notify}/>;
  if(kind==='task') return <TaskForm existing={id?state.tasks.find(t=>t.id===id):undefined} state={state} setState={setState} close={close} notify={notify}/>;
  if(kind==='exam') return <ExamForm existing={id?state.exams.find(e=>e.id===id):undefined} state={state} setState={setState} close={close} notify={notify}/>;
  if(kind==='event') return <EventForm existing={id?state.events.find(e=>e.id===id):undefined} setState={setState} close={close} notify={notify}/>;
  if(kind==='habit') return <HabitForm existing={id?state.habits.find(h=>h.id===id):undefined} setState={setState} close={close} notify={notify}/>;
  if(kind==='workout') return <WorkoutForm existing={id?state.workouts.find(w=>w.id===id):undefined} setState={setState} close={close} notify={notify}/>;
  if(kind==='goal') return <GoalForm existing={id?state.goals.find(g=>g.id===id):undefined} setState={setState} close={close} notify={notify}/>;
  return <ProfileForm state={state} setState={setState} close={close} notify={notify}/>;
}

function Modal({title,children,close}:{title:string;children:React.ReactNode;close:()=>void}){return <div className="modalback" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><div className="modal"><div className="modalhead"><h3>{title}</h3><button className="close" onClick={close}>×</button></div>{children}</div></div>}

function SubjectForm({existing,state,setState,close,notify}:{existing?:Subject;state:AppState;setState:React.Dispatch<React.SetStateAction<AppState>>;close:()=>void;notify:(s:string)=>void}){
  const [name,setName]=useState(existing?.name||'');const [target,setTarget]=useState(existing?.target||state.profile.targetAverage);const [notes,setNotes]=useState(existing?.notes||'');const [cats,setCats]=useState<Category[]>(existing?.categories.map(c=>({...c}))||[{id:uid(),name:'Schriftlich',weight:50},{id:uid(),name:'Mündlich',weight:50}]);const total=cats.reduce((s,c)=>s+Number(c.weight),0);
  const save=(e:FormEvent)=>{e.preventDefault();if(!name.trim()||!cats.length||Math.abs(total-100)>.01)return;setState(p=>({...p,subjects:existing?p.subjects.map(s=>s.id===existing.id?{...s,name:name.trim(),target,notes,categories:cats}:s):[...p.subjects,{id:uid(),name:name.trim(),target,notes,categories:cats,grades:[]}]}));notify(existing?'Fach aktualisiert':'Fach angelegt');close();};
  const del=()=>{if(!existing||!confirm(`Fach ${existing.name} wirklich löschen? Noten werden ebenfalls gelöscht.`))return;setState(p=>({...p,subjects:p.subjects.filter(s=>s.id!==existing.id),tasks:p.tasks.map(t=>t.subjectId===existing.id?{...t,subjectId:null}:t),exams:p.exams.filter(e=>e.subjectId!==existing.id)}));notify('Fach gelöscht');close();};
  return <Modal title={existing?'Fach bearbeiten':'Fach hinzufügen'} close={close}><form className="form" onSubmit={save}><div className="formgrid"><Field label="Name"><input className="input" value={name} onChange={e=>setName(e.target.value)} required/></Field><Field label="Zielnote"><NumberInput className="input" min="1" max="6" step="0.1" value={target} onChange={e=>setTarget(Number(e.target.value))}/></Field></div><Field label="Kategorien & Gewichtung">{cats.map((c,i)=><div className="categoryline" key={c.id}><input className="input" value={c.name} onChange={e=>setCats(x=>x.map((v,j)=>j===i?{...v,name:e.target.value}:v))}/><NumberInput className="input" min="0" max="100" value={c.weight} onChange={e=>setCats(x=>x.map((v,j)=>j===i?{...v,weight:Number(e.target.value)}:v))}/><button type="button" className="close" onClick={()=>setCats(x=>x.filter((_,j)=>j!==i))}>×</button></div>)}<button type="button" className="btn small" onClick={()=>setCats(x=>[...x,{id:uid(),name:'',weight:0}])}>Kategorie hinzufügen</button></Field>{Math.abs(total-100)>.01&&<div className="warning">Gewichtungen ergeben {total}%. Sie müssen zusammen genau 100% sein.</div>}<Field label="Notizen"><textarea className="textarea" value={notes} onChange={e=>setNotes(e.target.value)}/></Field><div className="actions">{existing&&<button type="button" className="btn danger" onClick={del}>Löschen</button>}<button type="button" className="btn" onClick={close}>Abbrechen</button><button className="btn primary" disabled={Math.abs(total-100)>.01}>Speichern</button></div></form></Modal>
}

function GradeForm({subject,existing,setState,close,notify}:{subject:Subject;existing?:any;setState:React.Dispatch<React.SetStateAction<AppState>>;close:()=>void;notify:(s:string)=>void}){const [categoryId,setCategoryId]=useState(existing?.categoryId||subject.categories[0]?.id||'');const [value,setValue]=useState(existing?.value||1.5);const [multiplier,setMultiplier]=useState(existing?.multiplier||1);const [date,setDate]=useState(existing?.date||isoToday());const [label,setLabel]=useState(existing?.label||'');const save=(e:FormEvent)=>{e.preventDefault();setState(p=>({...p,subjects:p.subjects.map(s=>s.id===subject.id?{...s,grades:existing?s.grades.map(g=>g.id===existing.id?{...g,categoryId,value,multiplier,date,label}:g):[...s.grades,{id:uid(),categoryId,value,multiplier,date,label}]}:s)}));notify(existing?'Note aktualisiert':'Note hinzugefügt');close();};const del=()=>{if(!existing)return;setState(p=>({...p,subjects:p.subjects.map(s=>s.id===subject.id?{...s,grades:s.grades.filter(g=>g.id!==existing.id)}:s)}));notify('Note gelöscht');close();};return <Modal title={existing?'Note bearbeiten':'Note hinzufügen'} close={close}><form className="form" onSubmit={save}><div className="formgrid"><Field label="Kategorie"><select className="select" value={categoryId} onChange={e=>setCategoryId(e.target.value)}>{subject.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Note"><NumberInput className="input" min="1" max="6" step="0.1" value={value} onChange={e=>setValue(Number(e.target.value))}/></Field><Field label="Gewichtung der Leistung"><select className="select" value={multiplier} onChange={e=>setMultiplier(Number(e.target.value))}><option value={0.5}>0,5×</option><option value={1}>1×</option><option value={2}>2×</option></select></Field><Field label="Datum"><input className="input" type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field></div><Field label="Bezeichnung"><input className="input" value={label} onChange={e=>setLabel(e.target.value)}/></Field><div className="actions">{existing&&<button type="button" className="btn danger" onClick={del}>Löschen</button>}<button type="button" className="btn" onClick={close}>Abbrechen</button><button className="btn primary">Speichern</button></div></form></Modal>}

